-- ARC · ejercicios nuevos para las planificaciones presenciales
insert into public.content_exercises (id, grp, name, muscle, equip, simple, tip, sort) values
  ('ARC-089', 'Glúteo y cadera', 'Aducción de cadera en máquina', 'Aductores', 'Máquina', 'En la máquina, con las almohadillas por dentro de las rodillas, juntas las piernas apretando y vuelves a abrir despacio.', 'Aguanta 1 segundo con las piernas juntas, baja en 3 segundos y para un segundo abajo, con las piernas bien abiertas.', 800),
  ('ARC-090', 'Cuádriceps', 'Prensa horizontal', 'Cuádriceps, glúteo', 'Máquina', 'En la prensa, con los pies en la plataforma, doblas las rodillas acercando el peso y empujas hasta casi estirar las piernas.', 'Baja en 3 segundos, micropausa abajo y empuja desde el talón sin bloquear las rodillas. Agárrate tirando de tu cuerpo hacia abajo.', 801),
  ('ARC-091', 'Gemelo', 'Gemelo en máquina', 'Gemelo, sóleo', 'Máquina', 'Con la punta de los pies en el borde, bajas los talones todo lo que puedas y subes de puntillas.', 'Baja en 3 segundos, aguanta 2 abajo estirando, sube rápido y aprieta 1 segundo arriba.', 802),
  ('ARC-092', 'Bíceps', 'Curl de bíceps en polea con barra', 'Bíceps braquial', 'Polea', 'De pie frente a la polea baja con una barra, doblas los codos subiendo la barra hacia el pecho y bajas despacio.', 'Baja estirando del todo sin perder la tensión y no subas los hombros al subir la barra.', 803),
  ('ARC-093', 'Abdomen', 'Crunch abdominal en máquina', 'Recto abdominal', 'Máquina', 'En la máquina, encoges el tronco llevando el pecho hacia la cadera y vuelves despacio.', 'Flexiona la columna sin mover la cadera, aguanta 1 segundo abajo y controla la vuelta.', 804),
  ('ARC-094', 'Femoral', 'Buenos días con barra', 'Isquiotibiales, glúteo, espalda baja', 'Barra', 'Con la barra en la espalda y las rodillas un poco dobladas, inclinas el tronco hacia delante llevando la cadera atrás y vuelves a subir.', 'Baja en 3 segundos, 1 segundo abajo y sube sin llegar a estirar del todo la cadera, para no perder la tensión en el femoral.', 805),
  ('ARC-095', 'Glúteo y cadera', 'Patada de rana en multipower', 'Glúteo mayor', 'Multipower + banco', 'Boca abajo en un banco bajo la multipower, con las plantas de los pies juntas en la barra, empujas hacia arriba apretando el glúteo.', 'Agárrate bien al banco, piernas algo más abiertas que los hombros y que las tibias sigan la línea de la barra.', 806),
  ('ARC-096', 'Tríceps', 'Extensión de tríceps en polea con barra V', 'Tríceps', 'Polea', 'De pie frente a la polea alta con la barra en V, estiras los codos empujando hacia abajo y vuelves despacio.', 'Inclínate un poco hacia delante, codos pegados al cuerpo, aguanta 1 segundo abajo y sube sin mover los codos.', 807),
  ('ARC-097', 'Hombro', 'Elevaciones laterales con mancuernas', 'Deltoide lateral', 'Mancuernas', 'De pie con una mancuerna en cada mano, subes los brazos hacia los lados hasta la altura de los hombros y bajas despacio.', 'Lleva las manos un poco hacia delante, inclínate ligeramente, aguanta 1 segundo arriba y controla la bajada.', 808)
on conflict (id) do nothing;

-- ARC · alta de Cynthia y Ana Belén como asesoradas de Luna (presencial con Adán). Se unen solas a su cuenta por el correo.
insert into public.coach_clients (coach_id, email, name)
select c.id, x.email, x.name
from (select id from public.profiles where role = 'coach' order by created_at nulls last limit 1) c
cross join (values ('cynthiatuset@gmail.com', 'Cynthia'), ('anabelen.hago@gmail.com', 'Ana Belén')) as x(email, name)
on conflict (coach_id, email) do update set name = excluded.name, updated_at = now();

-- Rutina de Cynthia (5 días)
