, "reps": "8–12", "rir": 0, "rest": 120}]}, {"name": "Glúteo", "ex": [{"id": "ARC-054", "sets": 3, "reps": "1×7–9 / 2×8–12", "rir": 1, "rest": 120}, {"id": "ARC-095", "sets": 2, "reps": "10–12", "rir": 1, "rest": 120}, {"id": "ARC-052", "sets": 2, "reps": "10–15 por pierna", "rir": 1, "rest": 120}, {"id": "ARC-X03", "sets": 2, "reps": "10–15 por pierna", "rir": 0, "rest": 90}, {"id": "ARC-060", "sets": 3, "reps": "8–12", "rir": 0, "rest": 105}, {"id": "ARC-093", "sets": 3, "reps": "10–15", "rir": 0, "rest": 90}]}]$arc$::jsonb, updated_at = now()
where email = 'cynthiatuset@gmail.com';

-- Comprobación: "unida" = sí si ya tiene cuenta en la app
select name, email, (client_id is not null) as unida, coalesce(jsonb_array_length(routine), 0) as dias from public.coach_clients
where email in ('cynthiatuset@gmail.com', 'anabelen.hago@gmail.com');
